// Enhanced Update table_2 code - Handle new deadlines + USE UUID for Google Sheets
const webhookNode = $('Webhook - Process Updates').first().json;

let webhookBody = webhookNode.body || webhookNode.query || webhookNode;

if (!webhookBody || Object.keys(webhookBody).length === 0) {
    console.log("❌ No webhook data received, stopping execution.");
    return [];
}

// Extract parameters safely
const taskUUID = webhookBody.task_UUID || webhookBody.UUID || null;
const token = webhookBody.token || webhookBody.update_token || null;
const newStatus = webhookBody.status || null;
const newComment = webhookBody.comment || '';
const dateCompleted = webhookBody.date_completed || null;
const batchId = webhookBody.batch_id || webhookBody.email_batch_id || null;
const requiresDeadline = webhookBody.requires_deadline === 'true';
const newDeadline = webhookBody.new_deadline || null;

console.log("🔥 Incoming webhook data:", webhookBody);
console.log(`Deadline requirements - requires: ${requiresDeadline}, new: ${newDeadline}`);

// Validate required fields
if (!taskUUID || !token) {
    console.log("❌ Missing task_id or token:", { taskId, token });
    return [];
}

// Determine final date completed
let finalDateCompleted = null;
if (newStatus === 'Completed') {
    const today = new Date();
    const allowedDates = [];
    for (let i = 0; i < 4; i++) {
        const d = new Date(today);
        d.setDate(today.getDate() - i);
        allowedDates.push(d.toISOString().split('T')[0]);
    }

    if (dateCompleted && allowedDates.includes(dateCompleted)) {
        finalDateCompleted = dateCompleted;
    } else {
        finalDateCompleted = allowedDates[0];
    }
}

// Prepare update table_3 - USE UUID INSTEAD OF NUMERIC ID
const updatePayload = {
    UUID: taskUUID,
    update_token: token,
    status: newStatus,
    comment: newComment,
    date_completed: finalDateCompleted,
    batch_id: batchId,
    success: true,
    requires_validation: true,
    processed_at: new Date().toISOString(),
    new_deadline: newDeadline
};

console.log('✅ Prepared task update table_3:', updatePayload);

return [{
    json: updatePayload
}];

// Enhanced Task update table_4 - NOW WITH SIMPLIFIED TOKEN VALIDATION
const tokenCheck = $('Validate Token Simple').first().json; // ← CHANGED: New node name
const webhookData = $('Webhook - Update table_1').first().json.query;

// ✅ CHECK IF TOKEN IS INVALID - SHOW ERROR PAGE
if (!tokenCheck.is_valid_token) {
  const errorMessage = tokenCheck.validation_message || 'Invalid or expired link';

  const errorHtml = `
