  console.log(`❌ Token validation failed: ${errorMessage}`);
  return [{ json: { html_content: errorHtml, success: false, error: errorMessage } }];
}

// ✅ TOKEN IS VALID - PROCEED WITH FORM
console.log('✅ Token validated successfully');

// Get deadline from table_6 parameters
const currentDeadline = webhookData.current_deadline;
const dateGiven = webhookData.date_given;

// Determine if this task needs a deadline
const hasExistingDeadline = currentDeadline && 
                           currentDeadline !== 'Not specified' && 
                           currentDeadline !== 'null' && 
                           currentDeadline !== 'undefined' &&
                           currentDeadline !== '';

// ✅ Calculate default deadline: 7 days from table_7 given
let defaultDeadline = '';
if (!hasExistingDeadline && dateGiven) {
    const givenDate = new Date(dateGiven);
    givenDate.setDate(givenDate.getDate() + 7);
    defaultDeadline = givenDate.toISOString().split('T')[0];
}

console.log(`Deadline from table_6: "${currentDeadline}", Has deadline: ${hasExistingDeadline}, Default deadline: ${defaultDeadline}`);

const taskDescription = webhookData.task_description;
const currentStatus = webhookData.current_status;
const recipientEmail = webhookData.recipient_email;
const POST_WEBHOOK_URL = '[URL]';

const htmlForm = `
<!DOCTYPE html>
<html>
<head>
    <title>Update table_8</title>
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <style>
        body { font-family: sans-serif; padding: 20px; background-color: #f4f7f9; }
        .container { max-width: 600px; margin: auto; background: white; padding: 30px; border-radius: 8px; box-shadow: 0 4px 6px rgba(0,0,0,0.1); }
        h1 { color: #333; }
        .task-info { background: #eef; padding: 15px; border-radius: 5px; margin-bottom: 20px; }
        label { display: block; margin-top: 15px; font-weight: bold; }
        select, textarea, input[type="date"] { width: 100%; padding: 10px; margin-top: 5px; border: 1px solid #ccc; border-radius: 4px; }
        button { background-color: #007bff; color: white; padding: 12px 20px; border: none; border-radius: 4px; cursor: pointer; margin-top: 20px; }
        .date-completed-section { display: none; margin-top: 15px; padding: 15px; background-color: #e8f5e8; border-radius: 5px; }
        .deadline-required-section { display: ${hasExistingDeadline ? 'none' : 'block'}; margin-top: 15px; padding: 15px; background-color: #fff3cd; border-radius: 5px; border-left: 4px solid #ffc107; }
        .completed-note { color: #27ae60; font-size: 14px; margin-top: 5px; }
        .deadline-note { color: #856404; font-size: 14px; margin-top: 5px; }
        .required-field::after { content: " *"; color: #e74c3c; }
    </style>
    <script>
        function toggleDateCompleted() {
            const statusSelect = document.getElementById('status');
            const dateSection = document.getElementById('dateCompletedSection');
            const dateInput = document.getElementById('dateCompleted');
            if (statusSelect.value === 'Completed') {
                dateSection.style.display = 'block';
                const today = new Date();
                const allowedDates = [];
                for (let i = 0; i < 4; i++) {
                    const d = new Date(today);
                    d.setDate(today.getDate() - i);
                    allowedDates.push(d.toISOString().split('T')[0]);
                }
                dateInput.value = allowedDates[0];
                dateInput.required = true;
                dateInput.setAttribute("min", allowedDates[3]);
                dateInput.setAttribute("max", allowedDates[0]);
            } else {
                dateSection.style.display = 'none';
                dateInput.value = '';
                dateInput.required = false;
            }
        }

        function validateDeadline() {
            const deadlineRequired = ${!hasExistingDeadline};
            if (deadlineRequired) {
                const deadlineInput = document.getElementById('newDeadline');
                if (!deadlineInput.value) {
                    alert('Please set a deadline for this task. This task currently has no deadline.');
                    deadlineInput.focus();
                    return false;
                }

                const selectedDate = new Date(deadlineInput.value);
                const today = new Date();
                const daysDiff = (selectedDate - today) / (1000 * 60 * 60 * 24);

                if (daysDiff > 30) {
                    if (!confirm('This deadline is more than 30 days away. Are you sure you need this much time? Note that this is subject to approval')) {
                        deadlineInput.focus();
                        return false;
                    }
                }
            }
            return true;
        }

        function validateForm() {
            const commentField = document.getElementById('comment');
            if (!commentField.value.trim()) {
                alert('Please provide a Task Update table_9 submitting.');
                commentField.focus();
                return false;
            }

            return validateDeadline();
        }

        window.onload = function() {
            toggleDateCompleted();

            const deadlineRequired = ${!hasExistingDeadline};
            if (deadlineRequired) {
                const today = new Date().toISOString().split('T')[0];
                const deadlineInput = document.getElementById('newDeadline');
                if (deadlineInput) {
                    deadlineInput.setAttribute('min', today);
                }
            }
        };
    </script>
</head>
<body>
    <div class="container">
