        </div>
        <form action="${POST_WEBHOOK_URL}" method="POST" onsubmit="return validateForm()">
            <input type="hidden" name="recipient_email" value="${recipientEmail}">
            <input type="hidden" name="batch_id" value="${webhookData.batch_id}">
            <input type="hidden" name="task_UUID" value="${webhookData.task_UUID}">
            <input type="hidden" name="token" value="${webhookData.token}">
            <input type="hidden" name="requires_deadline" value="${!hasExistingDeadline}">

            <label for="status" class="required-field">Status:</label>
            <select name="status" id="status" onchange="toggleDateCompleted()" required>
                <option value="Not started" ${currentStatus === 'Not started' ? 'selected' : ''}>Not Started</option>
                <option value="In progress" ${currentStatus === 'In progress' ? 'selected' : ''}>In Progress</option>
                <option value="Completed" ${currentStatus === 'Completed' ? 'selected' : ''}>Completed</option>
            </select>

            <div id="deadlineRequiredSection" class="deadline-required-section">
                <label for="newDeadline" class="required-field">Set Deadline (Required):</label>
                <input type="date" name="new_deadline" id="newDeadline" value="${defaultDeadline}" ${!hasExistingDeadline ? 'required' : ''}>
                <div class="deadline-note">
                    ${defaultDeadline ? `Task auto-column_2strong>${defaultDeadline}</strong> (7 days from table_10 date). Edit to change if needed.` : 'This task currently has no deadline. Please set a realistic deadline.'}
                </div>
            </div>

            <div id="dateCompletedSection" class="date-completed-section">
                <label for="dateCompleted">Date Completed:</label>
                <input type="date" name="date_completed" id="dateCompleted">
                <div class="completed-note">You can only select from table_11 and the last 3 days.</div>
            </div>

            <label for="comment" class="required-field">Task Update:</label>
            <textarea name="comment" id="comment" rows="4" placeholder="Type your task update/comment here..." required></textarea>

            <button type="submit">Submit Update</button>
        </form>
    </div>
</body>
</html>
`;

return [{ json: { html_content: htmlForm, success: true, requires_deadline: !hasExistingDeadline } }];

// Validate Token Simple - Just check if token + batch_id match (no complex expiration)
const sheetData = $('Lookup Task').first()?.json;
const webhookData = $('Webhook - Update table_1').first().json.query;

console.log('=== TOKEN VALIDATION DEBUG ===');
console.log('Webhook data received:', {
  task_id: webhookData.task_id,
  token: webhookData.token?.substring(0, 15) + '...',
  batch_id: webhookData.batch_id
});

// Check if task was found in sheet
if (!sheetData) {
  console.log('❌ Task not found in sheet');
  return [{
    json: {
      is_valid_token: false,
      validation_message: 'Task not found',
      last_email_batch_id: null
    }
  }];
}

// Log ALL sheet data to see column names
console.log('Sheet data columns:', Object.keys(sheetData));
console.log('Sheet data values:', {
  UUID: sheetData.UUID,
  Update_token: sheetData.Update_token?.substring(0, 15) + '...',
  update_token: sheetData.update_token?.substring(0, 15) + '...',
  last_email_batch_id: sheetData.last_email_batch_id,
  all_fields: sheetData
});

// Get the stored token (check both possible column names)
const storedToken = sheetData.Update_token || sheetData.update_token || sheetData['Update_token'];
const storedBatchId = sheetData.last_email_batch_id;

console.log('Comparison:', {
  storedToken: storedToken?.substring(0, 15) + '...',
  receivedToken: webhookData.token?.substring(0, 15) + '...',
  storedBatchId: storedBatchId,
  receivedBatchId: webhookData.batch_id
});

// Simple validation: token + batch_id must match
const tokenMatches = storedToken === webhookData.token;
const batchIdMatches = storedBatchId === webhookData.batch_id;
const isValidToken = tokenMatches && batchIdMatches;

// Determine validation message
let validationMessage = 'Success';
if (!isValidToken) {
  if (!storedToken) {
    validationMessage = 'No token found in database - email may not have been sent yet';
  } else if (!storedBatchId) {
    validationMessage = 'No batch ID found - email may not have been sent yet';
  } else if (!batchIdMatches) {
    validationMessage = 'Link expired - new email sent';
  } else if (!tokenMatches) {
    validationMessage = 'Invalid token';
  } else {
    validationMessage = 'Validation failed';
  }
}

console.log('Validation result:', {
  tokenMatches,
  batchIdMatches,
  isValidToken,
  message: validationMessage
});

return [{
  json: {
    id: sheetData.UUID,
    is_valid_token: isValidToken,
    last_email_batch_id: storedBatchId,
    validation_message: validationMessage
  }
}];

// Filter and Score Tasks - Replaces Postgres SQL filtering logic
const items = $input.all();
const currentDate = new Date();
currentDate.setHours(0, 0, 0, 0);

console.log(`Received ${items.length} total tasks from table_2`);

const filteredItems = items
  .map(item => {
    const task = item.json;

    // Skip completed tasks
    if (task.status === 'Completed') {
      return null;
    }

    // Skip if status is not "Not started" or "In progress"
    if (task.status !== 'Not started' && task.status !== 'In progress') {
      return null;
    }

    // Parse and validate task date
    let taskDate = null;
    if (task.date) {
      taskDate = new Date(task.date);
      taskDate.setHours(0, 0, 0, 0);

      // Only include 2026 tasks
      if (taskDate.getFullYear() !== 2026) {
        return null;
      }
    } else {
      // Skip tasks without a date
      return null;
    }

    // Parse deadline
    let deadline = null;
    if (task.deadline && 
        task.deadline !== 'Not specified' && 
        task.deadline !== 'null' && 
        task.deadline !== 'undefined' &&
        task.deadline !== '') {
      deadline = new Date(task.deadline);
      deadline.setHours(0, 0, 0, 0);
    }

    // Skip tasks with deadline more than 1 month in the past
    const oneMonthAgo = new Date(currentDate.getTime() - 30 * 24 * 60 * 60 * 1000);
    if (deadline && deadline < oneMonthAgo) {
      return null; // Expired tasks
    }

    // Calculate priority score
    let priorityScore = 0;
    let priorityLabel = 'Upcoming';

    if (!deadline) {
      priorityScore = 0;
      priorityLabel = 'No Deadline';
    } else {
      const diffTime = deadline - currentDate;
      const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));

      if (deadline < oneMonthAgo) {
        // Very old - should have been filtered above
        priorityLabel = 'Expired';
        priorityScore = -1;
      } else if (deadline < currentDate) {
        // Overdue - higher priority score (days overdue)
        priorityLabel = 'Overdue';
        priorityScore = Math.ceil((currentDate - deadline) / (1000 * 60 * 60 * 24));
      } else if (diffDays <= 7) {
        // Due soon - medium priority
        priorityLabel = 'Due Soon';
        priorityScore = 0;
      } else {
        // Future deadline - lower priority (days until due)
        priorityLabel = 'Upcoming';
        priorityScore = diffDays;
      }
    }

    // Only include tasks with priority_score >= 0
    if (priorityScore < 0) {
      return null;
    }

    return {
      json: {
        ...task,
        priority_score: priorityScore,
        priority_label: priorityLabel
      }
    };
  })
  .filter(item => item !== null);

// Sort by priority score DESC (most urgent first), then deadline ASC (earliest first)
filteredItems.sort((a, b) => {
  // First sort by priority score (higher = more urgent for overdue, lower = more urgent for upcoming)
  // For overdue tasks: higher score = more days overdue = more urgent
  // For upcoming tasks: lower score = fewer days until due = more urgent

  const scoreA = a.json.priority_score;
  const scoreB = b.json.priority_score;
  const labelA = a.json.priority_label;
  const labelB = b.json.priority_label;

  // Overdue tasks always come first
  if (labelA === 'Overdue' && labelB !== 'Overdue') return -1;
  if (labelA !== 'Overdue' && labelB === 'Overdue') return 1;

  // Both overdue: sort by days overdue (higher score = more overdue = first)
  if (labelA === 'Overdue' && labelB === 'Overdue') {
    return scoreB - scoreA;
  }

  // Due soon tasks come before upcoming tasks
  if (labelA === 'Due Soon' && labelB === 'Upcoming') return -1;
  if (labelA === 'Upcoming' && labelB === 'Due Soon') return 1;

  // No deadline tasks come last
  if (labelA === 'No Deadline' && labelB !== 'No Deadline') return 1;
  if (labelA !== 'No Deadline' && labelB === 'No Deadline') return -1;

  // Within same category, sort by actual deadline date
  const deadlineA = a.json.deadline ? new Date(a.json.deadline) : new Date('9999-12-31');
  const deadlineB = b.json.deadline ? new Date(b.json.deadline) : new Date('9999-12-31');

  return deadlineA - deadlineB;
});

console.log(`Filtered to ${filteredItems.length} tasks for email generation`);
console.log(`Priority breakdown:`, {
  overdue: filteredItems.filter(i => i.json.priority_label === 'Overdue').length,
  due_soon: filteredItems.filter(i => i.json.priority_label === 'Due Soon').length,
  upcoming: filteredItems.filter(i => i.json.priority_label === 'Upcoming').length,
  no_deadline: filteredItems.filter(i => i.json.priority_label === 'No Deadline').length
});

return filteredItems;

const emailData = $input.all();
const tokenUpdates = [];

emailData.forEach(email => {
    const tasksWithTokens = email.json.tasks_with_tokens || [];

    tasksWithTokens.forEach(task => {
        tokenUpdates.push({
            json: {
                UUID: task.UUID,
                id: task.id,
                update_token: task.update_token,
                email_batch_id: task.email_batch_id,
                token_used: false,
                token_created_at: new Date().toISOString(),
                recipient_email: email.json.to,
                batch_id: email.json.tasks_with_tokens[0]?.email_batch_id
            }
        });
    });
});
return tokenUpdates;

// This node formats the timestamp from table_16 WhatsApp Trigger.
return $input.all().map(item => {
    // Check if a timestamp exists and is a valid number.
    const unixTimestamp = item.json.timestamp;

    if (typeof unixTimestamp === 'number' && unixTimestamp > 0) {
        // WhatsApp timestamps are typically in seconds. Convert to milliseconds.
        const date = new Date(unixTimestamp * 1000);

        // Format the date as a full ISO 8601 string (e.g., "2025-09-14T13:26:47.000Z")
        item.json.formatted_date = date.toISOString();
    } else {
        // If no valid timestamp, use a fallback date.
        item.json.formatted_date = new Date().toISOString();
    }

    return item;
});

const summaryData = $input.all();
const sqlResults = $('Extract from table_18 Log').all();
const outputMessages = [];

summaryData.forEach((summary, index) => {
    const sqlResult = sqlResults[index];
    const firefliesId = sqlResult.json.fireflies_id;
    const meetingTitle = sqlResult.json.meeting_title;
    const meetingDate = sqlResult.json.meeting_date; // pass through as-is, don't touch
    const transcript = summary.json?.data?.summary?.action_items || 
                       'No action items were found in the summary data.';

    outputMessages.push({
        json: {
            messaging_product: meetingTitle,
            meeting_date: meetingDate,        // ISO string from table_20, untouched
            source: "Fireflies Meeting Transcript",
            messages: [{
                from: 'Zoom', 
                id: firefliesId,
                timestamp: Math.floor(Date.now() / 1000), // NOW, not meeting date
                body: transcript,
            }],
        }
    });
});

return outputMessages;

// === ENHANCED NAME MAPPING WITH ROLE/TEAM MATCHING ===

// Input nodes
const actionItems = $("AI output processing").all();
const nameMappings = $("Get row(s) in Names mapping sheet").all();

function generateUUID() {
    return '[ID]'.replace(/[xy]/g, function(c) {
        const r = Math.random() * 16 | 0;
        const v = c === 'x' ? r : (r & 0x3 | 0x8);
        return v.toString(16);
    });
}

// === NEW: ABBREVIATION DICTIONARY ===
const abbreviations = {
    'bi': 'business intelligence',
    'hr': 'human resources',
    'r&d': 'research and development',
    'r and d': 'research and development',
    'mt': 'management trainee',
    'mts': 'management trainee',
    'okl': 'okl',
    'obc': 'obc',
    'ofl': 'ofl',
    'tp': 'trade promotion',
    'ai': 'ai implementation',
    'cto': 'chief tech officer',
    'ccm': 'commercial capability manager'
};

// EXPcolumn_4==
function expandAbbreviations(text) {
    if (!text) return '';
    let expanded = text.toLowerCase();
    for (const [abbr, full] of Object.entries(abbreviations)) {
        const regex = new RegExp(`\\b${abbr}\\b`, 'gi');
        expanded = expanded.replace(regex, full);
    }
    return expanded;
}

// === ROLE-BASED MATCHING ===
function findByRole(actionOwner, meetingContexts = '') {
    const normalized = expandAbbreviations(actionOwner).toLowerCase().trim();
    const contextNormalized = expandAbbreviations(meetingContexts).toLowerCase().trim();


    // Extract role keywords (lead, manager, head, officer, etc.)
    const roleIndicators = ['lead', 'manager', 'head', 'officer', 'director', 'supervisor', 'coordinator'];
    const hasRoleIndicator = roleIndicators.some(indicator => normalized.includes(indicator));

    if (!hasRoleIndicator) return null;

    // Find candidates whose role_and_team matches the action_owner description
    const candidates = nameMappings.filter(mapping => {
        const roleText = expandAbbreviations(mapping.json.role_and_team || '').toLowerCase();
        const contexts = expandAbbreviations(mapping.json.Context_Mapping || '').toLowerCase();

        // Check if role description matches
        const roleMatch = roleIndicators.some(indicator => {
            if (normalized.includes(indicator)) {
                // Extract the role type (e.g., "recruitment" from "recruitment lead")
                const roleWords = normalized.replace(indicator, '').trim().split(/\s+/);
                return roleWords.every(word => 
                    word.length > 2 && roleText.includes(word)
                );
            }
            return false;
        });

        // Check if context matches
        const contextMatch = !contextNormalized || contexts.split(',').some(c => 
            contextNormalized.includes(c.trim()) || c.trim().includes(contextNormalized)
        );

        return roleMatch && contextMatch;
    });

    if (candidates.length === 1) {
        const match = candidates[0].json;
        return [{
            email: match.primary_email,
            name: match.primary_name,
            team: match.role_and_team,
            department: match.Context_Mapping
        }];
    } else if (candidates.length > 1) {
        // Use meeting context as tiebreaker
        const bestMatch = candidates.find(c => {
            const contexts = (c.json.Context_Mapping || '').toLowerCase();
            return contextNormalized && contexts.includes(contextNormalized);
        }) || candidates[0];

        const match = bestMatch.json;
        return [{
            email: match.primary_email,
            name: match.primary_name,
            team: match.role_and_team,
            department: match.Context_Mapping
        }];
    }

    return null;
}

// TEAM EXPANSION MATCHING (TARGET LEADERS ONLY) ===
function findByTeam(actionOwner, meetingContexts = '') {
    const normalized = expandAbbreviations(actionOwner).toLowerCase().trim();
    const contextNormalized = expandAbbreviations(meetingContexts).toLowerCase().trim();


    // Check if this is a team reference
    const teamIndicators = ['team', 'teams', 'group', 'members', 'staff', 'personnel'];
    const hasTeamIndicator = teamIndicators.some(indicator => normalized.includes(indicator));

    // Special case: "Team" with no specific identifier - must use meeting context
    const isGenericTeam = normalized === 'team' || normalized.trim() === 'the team';

    if (isGenericTeam && (!contextNormalized || contextNormalized === 'general')) {
        return null;
    }

    // Determine target context
    let targetContext = '';

    if (isGenericTeam) {
        // Use meeting context directly
        targetContext = contextNormalized;
    } else if (hasTeamIndicator) {
        // Extract team name from table_21 (e.g., "AI Implementation team" → "ai implementation")
        targetContext = normalized;
        teamIndicators.forEach(indicator => {
            targetContext = targetContext.replace(indicator, '').trim();
        });
    } else {
        // Not a team reference
        return null;
    }

    if (!targetContext) {
        return null;
    }

    // **KEY CHANGE**: Always filter for leadership roles only when team is mentioned
    const leadershipKeywords = ['lead', 'manager', 'head', 'director', 'supervisor', 'chief'];

    // Find team leaders matching the context
    const teamLeaders = nameMappings.filter(mapping => {
        const contexts = expandAbbreviations(mapping.json.Context_Mapping || '').toLowerCase();
        const roleText = expandAbbreviations(mapping.json.role_and_team || '').toLowerCase();

        // Check if any context matches
        const contextMatch = contexts.split(',').some(c => {
            const trimmed = c.trim();
            return trimmed.includes(targetContext) || targetContext.includes(trimmed);
        });

        if (!contextMatch) return false;

        // **CRITICAL**: Only include people with leadership roles
        const isLeader = leadershipKeywords.some(keyword => roleText.includes(keyword));

        return isLeader;
    });

    if (teamLeaders.length === 0) {
        return null;
    }


    // Return team leaders only
    return teamLeaders.map(leader => ({
        email: leader.json.primary_email,
        name: leader.json.primary_name,
        team: leader.json.role_and_team,
        department: leader.json.Context_Mapping
    }));
}

// === CONTEXT-AWARE EMAIL MATCHING FUNCTION===
function findEmailMappingWithContext(actionOwner, meetingContexts = '', messageContent = '', source = '') {
    if (!actionOwner || actionOwner.trim() === '') return null;

    const original = actionOwner.trim();
    const normalized = original.toLowerCase().trim();

    // --- Stage 1: Gather all potential candidates ---
const nameCandidates = nameMappings.filter(mapping => {
    const primary = (mapping.json.primary_name || '').toLowerCase().replace(/\s+/g, ' ').trim();
    const altNames = (mapping.json.alternative_names || '').toLowerCase().replace(/\s+/g, ' ').trim();
    const altNamesArray = altNames.split(/[,&/]/).map(x => x.trim());

    // Check for exact matches in alternative names first (highest priority)
    if (altNamesArray.includes(normalized)) return true;

    // Check for exact primary name match
    if (primary === normalized) return true;

    // Only do partial matching for multi-word searches (safer)
    if (normalized.includes(' ')) {
        return primary.includes(normalized) || normalized.includes(primary);
    }

    // For single words, only match if it's a complete word in the name
    const primaryWords = primary.split(' ');
    return primaryWords.includes(normalized);
});

    if (nameCandidates.length === 0) {
        return null;
    }


    // --- Stage 2: Apply disambiguation rules ---
    const cleanedSource = (source || '').toLowerCase().trim();
    const cleanedContext = (meetingContexts || '').toLowerCase().trim();

    const normalizeList = (text) => {
        if (!text) return [];
        return text
            .split(',')
            .map(s => s.trim().toLowerCase())
            .filter(Boolean);
    };

    const scoredCandidates = nameCandidates.map(mapping => {
        const name = mapping.json.primary_name;
        const email = mapping.json.primary_email;
        const meetings = normalizeList(mapping.json['Meetings Attended']);
        const contexts = normalizeList(mapping.json['Context_Mapping']);
        const roles = (mapping.json['role_and_team'] || '').toLowerCase();

        let score = 0;

        const primary = (mapping.json.primary_name || '').toLowerCase();
        const altNames = (mapping.json.alternative_names || '').toLowerCase();
        if (primary === normalized || altNames.split(',').map(x => x.trim()).includes(normalized)) {
            score += 10;
        } else if (primary.includes(normalized) || normalized.includes(primary) || altNames.includes(normalized)) {
            score += 5;
        }

        const meetingMatch = meetings.some(m => cleanedSource.includes(m));
        if (meetingMatch) {
            score += 8;
        }

        const contextMatch = contexts.some(c => cleanedContext.includes(c));
        if (contextMatch) {
            score += 6;
        }

        const roleWords = roles.split(/[,]/).map(x => x.trim());
        const roleMatch = roleWords.some(r =>
            meetingContexts.toLowerCase().includes(r) ||
            messageContent.toLowerCase().includes(r)
        );
        if (roleMatch) {
            score += 3;
        }

        return {
            mapping,
            score,
            breakdown: { name, email, score, meetings, contexts, roles }
        };
    });

    const maxScore = Math.max(...scoredCandidates.map(c => c.score));
    const topCandidates = scoredCandidates.filter(c => c.score === maxScore);

    if (topCandidates.length === 1) {
        const best = topCandidates[0].mapping.json;
        return [{
            email: best.primary_email,
            name: best.primary_name,
            team: best.role_and_team,
            department: best.Context_Mapping
        }];
    } else if (topCandidates.length > 1) {
        const best = topCandidates[0].mapping.json;
        return [{
            email: best.primary_email,
            name: best.primary_name,
            team: best.role_and_team,
            department: best.Context_Mapping
        }];
    }

    const fallback = nameCandidates[0].json;
    return [{
        email: fallback.primary_email,
        name: fallback.primary_name,
        team: fallback.role_and_team,
        department: fallback.Context_Mapping
    }];
}

// === UNIFIED MATCHING FUNCTION ===
function findMapping(actionOwner, meetingContexts = '', messageContent = '', source = '') {
