// Safe date parser - strips extra quotes and returns null if invalid
function safeParseDate(rawDate) {
    if (!rawDate) return null;
    try {
        const cleaned = String(rawDate).replace(/^["']+|["']+$/g, '').trim();
        if (!cleaned) return null;
        const d = new Date(cleaned);
        if (isNaN(d.getTime())) return null;
        return d.toISOString().split('T')[0];
    } catch(e) {
        return null;
    }
}

function parseDeadline(deadline, meetingDate = null) {
    if (!deadline || deadline === "Not specified") return null;

    const text = deadline.toLowerCase().trim();

    let today;
    if (meetingDate) {
        const d = new Date(meetingDate);
        today = isNaN(d.getTime()) ? new Date() : d;
    } else {
        today = new Date();
    }

    const formatDate = (date) => {
        if (!date || isNaN(date.getTime())) return null;
        return date.toISOString().split('T')[0];
    };

    function getNextWeekday(date, targetDay) {
        const currentDay = date.getDay();
        const daysUntilTarget = (targetDay - currentDay + 7) % 7;
        const result = new Date(date);
        result.setDate(date.getDate() + daysUntilTarget);
        return result;
    }

    function calculateFirstBusinessWeek(targetMonth, targetYear) {
        const firstOfMonth = new Date(targetYear, targetMonth, 1);
        const firstDayOfWeek = firstOfMonth.getDay();

        let weekStart, weekEnd;

        if (firstDayOfWeek === 6 || firstDayOfWeek === 0 || firstDayOfWeek === 1) {
            weekStart = (firstDayOfWeek === 1) ? new Date(firstOfMonth) : getNextWeekday(firstOfMonth, 1);
            weekEnd = new Date(weekStart);
            weekEnd.setDate(weekStart.getDate() + 4);
        } else if (firstDayOfWeek === 2) {
            weekStart = new Date(firstOfMonth);
            weekEnd = new Date(weekStart);
            weekEnd.setDate(weekStart.getDate() + 3);
        } else {
            weekStart = getNextWeekday(firstOfMonth, 1);
            weekEnd = new Date(weekStart);
            weekEnd.setDate(weekStart.getDate() + 4);
        }

        return { start: weekStart, end: weekEnd };
    }

    if (text.includes('today') || text.includes('immediately')) {
        return formatDate(today);
    }

    if (text.includes('tomorrow')) {
        const tomorrow = new Date(today);
        tomorrow.setDate(tomorrow.getDate() + 1);
        return formatDate(tomorrow);
    }

    if (text.includes('end of') && text.includes('first week') && text.includes('next month')) {
        const nextMonth = today.getMonth() + 1;
        const nextYear = nextMonth > 11 ? today.getFullYear() + 1 : today.getFullYear();
        const adjustedMonth = nextMonth > 11 ? 0 : nextMonth;
        const { end } = calculateFirstBusinessWeek(adjustedMonth, nextYear);
        return formatDate(end);
    }

    if (text.includes('first week') && text.includes('next month')) {
        const nextMonth = today.getMonth() + 1;
        const nextYear = nextMonth > 11 ? today.getFullYear() + 1 : today.getFullYear();
        const adjustedMonth = nextMonth > 11 ? 0 : nextMonth;
        const { start } = calculateFirstBusinessWeek(adjustedMonth, nextYear);
        return formatDate(start);
    }

    if (text.includes('next week')) {
        const nextMonday = getNextWeekday(today, 1);
        if (nextMonday.getTime() === today.getTime() && today.getDay() === 1) {
            nextMonday.setDate(nextMonday.getDate() + 7);
        }
        return formatDate(nextMonday);
    }

    if (text.includes('eow') || text.includes('end of week') || text.includes('end of the week')) {
        const friday = getNextWeekday(today, 5);
        if (today.getDay() === 5) {
            return formatDate(today);
        }
        return formatDate(friday);
    }

    const daysOfWeek = ['sunday', 'monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday'];
    for (let i = 0; i < daysOfWeek.length; i++) {
        if (text.includes(daysOfWeek[i])) {
            const targetDay = getNextWeekday(today, i);
            if (targetDay.getTime() === today.getTime()) {
                targetDay.setDate(targetDay.getDate() + 7);
            }
            return formatDate(targetDay);
        }
    }

    if (text.includes('by friday')) {
        const friday = getNextWeekday(today, 5);
        return formatDate(friday);
    }

    const daysMatch = text.match(/(\d+)\s+days?/);
    if (daysMatch) {
        const future = new Date(today);
        future.setDate(future.getDate() + parseInt(daysMatch[1]));
        return formatDate(future);
    }

    const weeksMatch = text.match(/(\d+)\s+weeks?/);
    if (weeksMatch) {
        const future = new Date(today);
        future.setDate(future.getDate() + (parseInt(weeksMatch[1]) * 7));
        return formatDate(future);
    }

    if (text.includes('next month') && !text.includes('first week')) {
        const nextMonth = today.getMonth() + 1;
        const nextYear = nextMonth > 11 ? today.getFullYear() + 1 : today.getFullYear();
        const adjustedMonth = nextMonth > 11 ? 0 : nextMonth;
        const firstOfNextMonth = new Date(nextYear, adjustedMonth, 1);
        return formatDate(firstOfNextMonth);
    }

    const months = ['january', 'february', 'march', 'april', 'may', 'june', 
                    'july', 'august', 'september', 'october', 'november', 'december'];
    for (let i = 0; i < months.length; i++) {
        if (text.includes(months[i])) {
            let targetYear = today.getFullYear();
            if (i < today.getMonth()) {
                targetYear++;
            }
            const monthEnd = new Date(targetYear, i + 1, 0);
            return formatDate(monthEnd);
        }
    }

    if (text.includes('q1') || text.includes('first quarter')) {
        const year = today.getMonth() > 2 ? today.getFullYear() + 1 : today.getFullYear();
        return formatDate(new Date(year, 2, 31));
    }
    if (text.includes('q2') || text.includes('second quarter')) {
        const year = today.getMonth() > 5 ? today.getFullYear() + 1 : today.getFullYear();
        return formatDate(new Date(year, 5, 30));
    }
    if (text.includes('q3') || text.includes('third quarter')) {
        const year = today.getMonth() > 8 ? today.getFullYear() + 1 : today.getFullYear();
        return formatDate(new Date(year, 8, 30));
    }
    if (text.includes('q4') || text.includes('fourth quarter')) {
        const year = today.getMonth() > 11 ? today.getFullYear() + 1 : today.getFullYear();
        return formatDate(new Date(year, 11, 31));
    }

    return null;
}

function detectMeetingContext(source, meetingTitle, actionText) {
    const text = actionText.toLowerCase();

    const meetingToContexts = {
        "HR & Admin Meeting": ["Human Resources", "Admin"],
