        "Quality & Regulatory": ['quality', 'qc', 'qa', 'testing', 'compliance', 'audit', 'specification', 'standard'],
        "Tech team": ['tech', 'software', 'system', 'digital', 'application', 'platform', 'api', 'server', 'infrastructure'],
        "ORBIT": ['orbit', 'satellite', 'tracking', 'navigation', 'telemetry'],
        "Senior Management": ['executive', 'board', 'director', 'approval', 'leadership', 'ceo', 'md'],
        "Management": ['manager', 'supervisor', 'strategy', 'oversight', 'coordination'],
        "Project": ['project', 'investment', 'timeline', 'implementation']
    };

    if (source.toLowerCase().includes("whatsapp")) {
        const matchedContexts = Object.entries(keywordMap)
            .filter(([context, keywords]) => keywords.some(k => text.includes(k)))
            .map(([context]) => context);
        return matchedContexts.length > 0 ? matchedContexts.join(", ") : "General";
    }

    let potentialContexts = [];
    for (const [meeting, contexts] of Object.entries(meetingToContexts)) {
        if (meetingTitle.toLowerCase().includes(meeting.toLowerCase())) {
            potentialContexts = [...contexts];
            break;
        }
    }

    if (potentialContexts.length === 0) {
        const matchedContexts = Object.entries(keywordMap)
            .filter(([context, keywords]) => keywords.some(k => text.includes(k)))
            .map(([context]) => context);
        return matchedContexts.length > 0 ? matchedContexts.join(", ") : "General";
    }

    const matched = potentialContexts.filter(ctx =>
        (keywordMap[ctx] || []).some(k => text.includes(k))
    );

    if (matched.length > 0) return matched.join(", ");
    return potentialContexts.join(", ");
}

