// ✅ Secure crypto definition (works in n8n sandbox)
const crypto = globalThis.crypto || undefined;

// ✅ Cryptographically secure token generator
function generateSecureToken() {
    try {
        if (crypto && crypto.getRandomValues) {
            const array = new Uint8Array(32);
            crypto.getRandomValues(array);
            return Array.from(array, b => b.toString(16).padStart(2, '0')).join('');
        } else {
            // Fallback: Math.random (less secure, but sandbox-safe)
            return Array.from({ length: 32 }, () =>
                Math.floor(Math.random() * 256).toString(16).padStart(2, '0')
            ).join('');
        }
    } catch (err) {
        console.warn("Crypto unavailable – using fallback RNG:", err);
        return Array.from({ length: 32 }, () =>
            Math.floor(Math.random() * 256).toString(16).padStart(2, '0')
        ).join('');
    }
}

