function getStatusColor(status) {
    if (!status) return '#95a5a6';
    const lowerStatus = (status || '').toLowerCase();
    if (lowerStatus.includes('not started')) return '#e74c3c';
    if (lowerStatus.includes('in progress')) return '#f39c12';
    if (lowerStatus.includes('completed')) return '#27ae60';
    return '#95a5a6';
}

// Helper function to format deadline as YYYY-MM-DD
function formatDeadlineForEmail(deadline) {
    if (!deadline) return 'Not specified';

    // If it's already in YYYY-MM-DD format, return as is
    if (typeof deadline === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(deadline)) {
        return deadline;
    }

    // If it's a full ISO date, extract just the date part
    if (typeof deadline === 'string' && deadline.includes('T')) {
        return deadline.split('T')[0];
    }

    return deadline;
}

// Helper function to calculate days until/past deadline
function getDeadlineStatus(deadline) {
    if (!deadline) return { label: null, daysCount: null };

    let dateString = deadline;
    if (deadline.includes('T')) {
        dateString = deadline.split('T')[0];
    }

    const deadlineDate = new Date(dateString + 'T00:00:00Z');
    const today = new Date();
    today.setHours(0, 0, 0, 0);

    const diffTime = deadlineDate - today;
    const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));

    if (diffDays < 0) {
        return { label: 'Overdue', daysCount: Math.abs(diffDays) };
    } else if (diffDays <= 7) {
        return { label: 'Due Soon', daysCount: diffDays };
    }

    return { label: null, daysCount: null };
}

// Helper function to generate priority badge only for urgent tasks
function getPriorityBadge(deadlineStatus) {
    if (!deadlineStatus.label) return '';

    if (deadlineStatus.label === 'Overdue') {
        return `<span style="background: #e74c3c; color: white; padding: 4px 12px; border-radius: 12px; font-size: 12px; font-weight: bold; margin-left: 10px;">🚨 OVERDUE (${deadlineStatus.daysCount} day${deadlineStatus.daysCount > 1 ? 's' : ''})</span>`;
    } else if (deadlineStatus.label === 'Due Soon') {
        return `<span style="background: #f39c12; color: white; padding: 4px 12px; border-radius: 12px; font-size: 12px; font-weight: bold; margin-left: 10px;">⚠️ DUE IN ${deadlineStatus.daysCount} DAY${deadlineStatus.daysCount > 1 ? 'S' : ''}</span>`;
    }

    return '';
}

